wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};
use crate::aap::caps::types::Intent;

const MAX_QUESTION_BYTES: usize = 512;
const MAX_TOOL_ROUNDS: usize = 3;

const SYSTEM: &str = "You answer customer support questions using only the supplied \
knowledge. If you need more material, request the `lookup` tool with a short query.";

struct Node;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

fn error_result(message: &str) -> ResponseResult {
    ResponseResult::Error(LlmError {
        message: message.to_string(),
    })
}

fn build_prompt(ctx: &ConversationContext, extra: &str) -> String {
    let mut prompt = String::new();
    prompt.push_str("Intent: ");
    prompt.push_str(intent_label(ctx.intent));
    prompt.push('\n');
    prompt.push_str("Question: ");
    prompt.push_str(&ctx.question);
    prompt.push('\n');
    prompt.push_str("Knowledge:\n");
    for item in &ctx.knowledge {
        prompt.push_str("- ");
        prompt.push_str(item);
        prompt.push('\n');
    }
    prompt.push_str(extra);
    prompt
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // The `requires` clause already holds for every input; this guard
        // only keeps the body total if the bound is ever violated.
        if ctx.question.len() > MAX_QUESTION_BYTES {
            return error_result("question exceeds 512 bytes");
        }

        let mut prompt = build_prompt(&ctx, "");
        let mut rounds = 0usize;

        loop {
            match tool_llm::generate(SYSTEM, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(request) => {
                    if rounds >= MAX_TOOL_ROUNDS {
                        return error_result("tool round limit exceeded");
                    }
                    rounds += 1;

                    // Only the `lookup` tool is in this node's scope.
                    if request.tool != "lookup" {
                        return error_result("requested tool is not in scope");
                    }
                    if request.query.len() > MAX_QUESTION_BYTES {
                        return error_result("tool query exceeds 512 bytes");
                    }

                    let hits = kb_read::lookup(&request.query);
                    let extra = format!(
                        "Tool lookup({}) returned:\n{}\n",
                        request.query,
                        hits.join("\n"),
                    );
                    prompt = build_prompt(&ctx, &extra);
                }
            }
        }
    }
}

export!(Node);
```

